from pathlib import Path
import base64, gzip

A=Path('buildsrc/NAR-Mix/app/src/main/assets')
js=A/'app.js'; css=A/'app.css'
s=js.read_text()
c=css.read_text()
marker='NAR BETA 5.0 — APPROVED 10-SCREEN LOCK'
if marker in s:
    raise SystemExit('NAR Beta 5.0 already applied')

JS_B64=''''''
CSS_B64=''''''

snippet=gzip.decompress(base64.b64decode(JS_B64)).decode()
styles=gzip.decompress(base64.b64decode(CSS_B64)).decode()
anchor=s.rfind('})();')
if anchor < 0:
    raise SystemExit('NAR app closure not found')
s=s[:anchor]+'\n'+snippet+'\n'+s[anchor:]
c += '\n'+styles+'\n'
js.write_text(s)
css.write_text(c)
print('Applied NAR Beta 5.0 approved 10-screen lock')
